#!/usr/bin/env python3
"""Replace autogenerated related-page blocks with same-college, title-anchored links."""
from pathlib import Path
from urllib.parse import urlparse
from bs4 import BeautifulSoup
import json
import re

ROOT = Path(__file__).resolve().parents[1]
BASE = "https://collegedecoded.in"
INDEX = ROOT / "data" / "management-live-colleges.json"
VERCEL = ROOT / "vercel.json"
SKIP_PARTS = {".git", "node_modules", ".github", ".vercel"}
SKIP_FILES = {"404.html", "index.html", "college-guides.html", "colleges.html", "methodology.html"}

data = json.loads(INDEX.read_text(encoding="utf-8")) if INDEX.exists() else {"colleges": []}
redirects = json.loads(VERCEL.read_text(encoding="utf-8")).get("redirects", []) if VERCEL.exists() else []
redirect_map = {}
for rule in redirects:
    source = rule.get("source", "")
    destination = rule.get("destination", "")
    if source.startswith("/") and ":" not in source:
        src = source.rstrip("/")
        if src.endswith(".html"):
            src = src[:-5]
        redirect_map[src.lstrip("/")] = destination.rstrip("/").lstrip("/")

college_by_slug = {}
for name, url in data.get("colleges", []):
    slug = urlparse(url).path.strip("/")
    if slug:
        canonical_slug = redirect_map.get(slug, slug)
        college_by_slug[canonical_slug] = name

pages = {}
for path in ROOT.glob("*.html"):
    if path.name in SKIP_FILES:
        continue
    slug = path.stem
    if slug in redirect_map:
        continue
    raw = path.read_text(encoding="utf-8", errors="replace")
    soup = BeautifulSoup(raw, "html.parser")
    title_node = soup.find("title")
    title = title_node.get_text(" ", strip=True) if title_node else slug.replace("-", " ").title()
    title = re.sub(r"\s*\|\s*CollegeDecoded\s*$", "", title, flags=re.I).strip()
    title = re.sub(r"(?:…|\.\.\.)\s*$", "", title).strip()
    pages[slug] = {"path": path, "soup": soup, "title": title}

def college_for(slug):
    matches = [base for base in college_by_slug if slug == base or slug.startswith(base + "-")]
    if not matches:
        return None, None
    base = max(matches, key=len)
    return base, college_by_slug[base]

def topic(slug, base):
    suffix = slug[len(base):].strip("-") if slug != base else ""
    lower = suffix.lower()
    if not suffix:
        return "overview"
    if "placement" in lower:
        return "placement"
    if "admission" in lower or "application" in lower:
        return "admission"
    if "fee" in lower or "cost" in lower:
        return "fees"
    if "hostel" in lower or "campus" in lower:
        return "campus"
    if any(x in lower.split("-") for x in ("mba", "pgdm", "pgp", "pgpx", "pgpba", "emba", "btech", "bba", "bcom", "mca", "mtech", "phd")):
        return "programme"
    if "cutoff" in lower or "cut-off" in lower:
        return "cutoff"
    return "other"

def score(current_topic, candidate_topic):
    priorities = {
        "overview": {"overview": 0, "admission": 10, "fees": 9, "placement": 8, "programme": 7, "campus": 6, "cutoff": 5, "other": 1},
        "placement": {"overview": 10, "admission": 9, "fees": 8, "programme": 7, "campus": 6, "cutoff": 5, "placement": 0, "other": 1},
        "admission": {"overview": 10, "fees": 9, "placement": 8, "programme": 7, "cutoff": 6, "campus": 5, "admission": 0, "other": 1},
        "fees": {"overview": 10, "admission": 9, "placement": 8, "programme": 7, "campus": 6, "cutoff": 5, "fees": 0, "other": 1},
        "programme": {"overview": 10, "placement": 9, "fees": 8, "admission": 7, "campus": 6, "cutoff": 5, "programme": 4, "other": 1},
        "campus": {"overview": 10, "admission": 9, "fees": 8, "placement": 7, "programme": 6, "campus": 0, "other": 1},
        "cutoff": {"overview": 10, "admission": 9, "fees": 8, "placement": 7, "programme": 6, "cutoff": 0, "other": 1},
        "other": {"overview": 10, "admission": 8, "fees": 7, "placement": 6, "programme": 5, "campus": 4, "cutoff": 3, "other": 1},
    }
    return priorities.get(current_topic, priorities["other"]).get(candidate_topic, 0)

stats = {"pages_scanned": 0, "blocks_replaced": 0, "blocks_added": 0, "blocks_removed": 0, "pages_without_four_related_pages": 0}
for slug, record in pages.items():
    path, soup = record["path"], record["soup"]
    stats["pages_scanned"] += 1
    old_blocks = list(soup.select("nav.seo-cluster-links, nav[aria-label='Related college pages'], .related-colleges-internal-links"))
    for old in old_blocks:
        old.decompose()
    if old_blocks:
        stats["blocks_removed"] += len(old_blocks)
    base, college_name = college_for(slug)
    if not base:
        if old_blocks:
            path.write_text(str(soup), encoding="utf-8")
        continue
    current_topic = topic(slug, base)
    candidates = []
    for other_slug, other in pages.items():
        if other_slug == slug or not (other_slug == base or other_slug.startswith(base + "-")):
            continue
        # Do not link year-specific twins when an evergreen equivalent exists.
        if re.search(r"-20\d{2}$", other_slug):
            evergreen = re.sub(r"-20\d{2}$", "", other_slug)
            if evergreen in pages:
                continue
        candidate_topic = topic(other_slug, base)
        value = score(current_topic, candidate_topic)
        if value <= 0:
            continue
        candidates.append((value, other_slug, other["title"], candidate_topic))
    candidates.sort(key=lambda row: (-row[0], row[1]))
    selected = candidates[:6]

    if len(selected) < 4:
        stats["pages_without_four_related_pages"] += 1
        path.write_text(str(soup), encoding="utf-8")
        continue

    nav = soup.new_tag("nav", attrs={"class": "seo-cluster-links", "aria-label": "Related college pages"})
    heading = soup.new_tag("strong")
    heading.string = "Explore related pages"
    nav.append(heading)
    listing = soup.new_tag("ul")
    for _, other_slug, title, _ in selected:
        li = soup.new_tag("li")
        a = soup.new_tag("a", href="/" + other_slug)
        a.string = title or other_slug.replace("-", " ").title()
        li.append(a)
        listing.append(li)
    nav.append(listing)
    main = soup.find("main")
    if main:
        main.append(nav)
    elif soup.body:
        soup.body.append(nav)
    path.write_text(str(soup), encoding="utf-8")
    stats["blocks_replaced"] += 1

print("CURATED RELATED LINKS: " + ", ".join(f"{key}={value}" for key, value in stats.items()))
